using System.IO; using System.Windows.Media.Imaging;
namespace DG;
// לוגו התוכנה (מוטמע בקוד, ללא קובץ חיצוני)
static class Logo {
  const string B64 = "";
  static BitmapImage? img;
  public static BitmapImage Src { get {
    if (img == null) { var b = new BitmapImage(); b.BeginInit(); b.CacheOption = BitmapCacheOption.OnLoad; b.StreamSource = new MemoryStream(Convert.FromBase64String(B64)); b.EndInit(); b.Freeze(); img = b; }
    return img;
  } }
}
